import JSON

"""
	gen( p, lambda, name )

Generate fixture data and write to file.

The quantile is evaluated in extended precision from the textbook formula `-ln(1-p) / lambda`, as forming `1-p` in double precision rounds away the low-order bits of `p` (all of them for `p < 2^-53`).

# Arguments

* `p`: input value
* `lambda`: rate parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> p = rand( 1000 );
julia> lambda = rand( 1000 ) .* 100.0;
julia> gen( p, lambda, "data.json" );
```
"""
function gen( p, lambda, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( .-log.( 1 .- BigFloat.( p ) ) ./ BigFloat.( lambda ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("p", p),
		("lambda", lambda),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Small `p`:
p = exp10.( range( -300.0, stop = -1.0, length = 1000 ) );
lambda = ( rand( 1000 ) .* 100.0 ) .+ 0.1;
gen( p, lambda, "small_p.json" );
